struct TicTacToe{n:i32,r:Vec<i32>,c:Vec<i32>,d1:i32,d2:i32}impl TicTacToe{fn new(n:i32)->Self{Self{n,r:vec![0;n as usize],c:vec![0;n as usize],d1:0,d2:0}}fn make_move(&mut self,row:i32,col:i32,player:i32)->i32{let v=if player==1{1}else{-1};self.r[row as usize]+=v;self.c[col as usize]+=v;if row==col{self.d1+=v}if row+col==self.n-1{self.d2+=v}if self.r[row as usize].abs()==self.n||self.c[col as usize].abs()==self.n||self.d1.abs()==self.n||self.d2.abs()==self.n{player}else{0}}}
